from collections import Counter

def solve(nums, k):
    counts = Counter(nums)
    unique_nums = list(counts.keys())
    freqs = list(counts.values())

    def quickselect(arr, left, right, k):
        pivot = arr[right]
        i = left
        for j in range(left, right):
            if arr[j] <= pivot:
                arr[i], arr[j] = arr[j], arr[i]
                i += 1
        arr[i], arr[right] = arr[right], arr[i]
        if i == k:
            return arr[i]
        elif i < k:
            return quickselect(arr, i + 1, right, k)
        else:
            return quickselect(arr, left, i - 1, k)

    def select_kth_largest(arr, k):
        return quickselect(arr.copy(), 0, len(arr) - 1, k - 1)

    pivot = select_kth_largest(freqs, k)
    result = [num for num, freq in zip(unique_nums, freqs) if freq == pivot]
    return result
